class Solution {
    string makeAbbr(const string& w, int k) {
        if ((int)w.size() - 1 - k <= 1) return w;
        return w.substr(0, k) + to_string((int)w.size() - 1 - k) + w.back();
    }
public:
    vector<string> wordsAbbreviation(vector<string>& words) {
        int n = words.size();
        vector<int> prefixLens(n, 1);
        vector<string> ans(n);
        for (int i = 0; i < n; i++) ans[i] = makeAbbr(words[i], 1);

        while (true) {
            unordered_map<string, vector<int>> groups;
            for (int i = 0; i < n; i++) {
                groups[ans[i]].push_back(i);
            }
            bool hasConflict = false;
            for (auto& [abbr, indices] : groups) {
                if (indices.size() > 1) {
                    hasConflict = true;
                    for (int idx : indices) {
                        prefixLens[idx]++;
                        ans[idx] = makeAbbr(words[idx], prefixLens[idx]);
                    }
                }
            }
            if (!hasConflict) break;
        }
        return ans;
    }
};

class Solution {
    private String makeAbbr(String w, int k) {
        if (w.length() - 1 - k <= 1) return w;
        return w.substring(0, k) + (w.length() - 1 - k) + w.charAt(w.length() - 1);
    }

    public List<String> wordsAbbreviation(List<String> words) {
        int n = words.size();
        int[] prefixLens = new int[n];
        Arrays.fill(prefixLens, 1);
        List<String> ans = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            ans.add(makeAbbr(words.get(i), 1));
        }

        while (true) {
            Map<String, List<Integer>> groups = new HashMap<>();
            for (int i = 0; i < n; i++) {
                groups.computeIfAbsent(ans.get(i), k -> new ArrayList<>()).add(i);
            }
            boolean hasConflict = false;
            for (List<Integer> indices : groups.values()) {
                if (indices.size() > 1) {
                    hasConflict = true;
                    for (int idx : indices) {
                        prefixLens[idx]++;
                        ans.set(idx, makeAbbr(words.get(idx), prefixLens[idx]));
                    }
                }
            }
            if (!hasConflict) break;
        }
        return ans;
    }
}

var wordsAbbreviation = function(words) {
    const n = words.length;
    const prefixLens = new Array(n).fill(1);

    function makeAbbr(w, k) {
        if (w.length - 1 - k <= 1) return w;
        return w.slice(0, k) + (w.length - 1 - k) + w[w.length - 1];
    }

    const ans = words.map(w => makeAbbr(w, 1));

    while (true) {
        const groups = new Map();
        for (let i = 0; i < n; i++) {
            if (!groups.has(ans[i])) groups.set(ans[i], []);
            groups.get(ans[i]).push(i);
        }
        let hasConflict = false;
        for (const indices of groups.values()) {
            if (indices.length > 1) {
                hasConflict = true;
                for (const idx of indices) {
                    prefixLens[idx]++;
                    ans[idx] = makeAbbr(words[idx], prefixLens[idx]);
                }
            }
        }
        if (!hasConflict) break;
    }
    return ans;
};
